const CACHE='poppy-v8';
const ASSETS=["./","./index.html","./styles.css","./app.js","./document/model.js","./document/validate.js","./scene/matrix.js","./scene/shapes.js","./scene/mesh.js","./scene/shadow.js","./animation/curves.js","./animation/sequence.js","./ui/sequence.js","./ui/layer-menu.js","./timeline/graph.js","./scene/mesh-edit.js","./ui/mesh-colour.js","./scene/contour.js","./scene/strokes.js","./export/png.js","./scene/boolean.js","./vendor/polygon-clipping.js","./ui/context.js","./ui/shapes-menu.js","./scene/svg-path.js","./ui/editor.js","./ui/help.js","./scene/operations.js","./animation/evaluate.js","./renderer/svg.js","./input/stage.js","./timeline/timeline.js","./ui/properties.js","./ui/demo.js","./audio/audio.js","./persistence/store.js","./persistence/svg-import.js","./export/exporter.js","./export/render.js","./export/codecs.js","./vendor/mp4-muxer.js","./vendor/webm-muxer.js"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(new URL(url,self.location).href,{cache:'reload'})))).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return r;}).catch(()=>caches.match(event.request,{ignoreSearch:true})));});
